/**
 * Pure period and proration arithmetic shared by the renewal job and the
 * billing service's mid-period charges.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsInPeriod(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Same day next month (or next year, for annual), clamped to the target
 * month's last day when it has none — 31 January rolls to 28 February, and
 * that clamped day carries forward next time (28 February → 28 March).
 */
export function addPeriod(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInPeriod(interval));
}

function addMonthsClamped(date: Date, months: number): Date {
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth();
  const day = date.getUTCDate();

  const total = month + months;
  const targetYear = year + Math.floor(total / 12);
  const targetMonth = ((total % 12) + 12) % 12;
  const lastDayOfTargetMonth = new Date(
    Date.UTC(targetYear, targetMonth + 1, 0),
  ).getUTCDate();
  const clampedDay = Math.min(day, lastDayOfTargetMonth);

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      clampedDay,
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/** The full charge for one period of `plan`, in cents. */
export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsInPeriod(interval)
  );
}

/** Whole days between `start` and `end`, rounded, never less than one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const ms = new Date(end).getTime() - new Date(start).getTime();
  return Math.max(1, Math.round(ms / MS_PER_DAY));
}

/** Whole or started days left from `now` to `periodEnd`; zero once reached. */
export function daysLeftInPeriod(now: Date, periodEnd: IsoTimestamp): number {
  const ms = new Date(periodEnd).getTime() - now.getTime();
  return ms <= 0 ? 0 : Math.ceil(ms / MS_PER_DAY);
}

/** The full-period amount scaled by days left over days in period, rounded down. */
export function prorate(
  fullAmountCents: number,
  daysLeft: number,
  daysTotal: number,
): number {
  if (daysLeft <= 0 || fullAmountCents <= 0) return 0;
  return Math.floor((fullAmountCents * daysLeft) / daysTotal);
}

