/** Sets the current period, leaving plan, interval and status untouched. */
export async function advanceSubscriptionPeriod(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Moves straight to a chosen plan with a fresh period, bypassing the trial flow. */
export async function setPlanAndPeriod(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: "active",
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** A cancellation taking effect: drop to the free plan with a fresh monthly period. */
export async function applyCancellationEnd(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
