export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  let subscription: Subscription;

  if (current.plan === "free" && input.plan !== "free") {
    const periodStart = toIsoTimestamp(now);
    const periodEnd = toIsoTimestamp(addPeriod(now, input.interval));

    subscription = await subscriptionRepo.setPlanAndPeriod(
      input.orgId,
      input.plan,
      input.interval,
      periodStart,
      periodEnd,
    );

    await issueInvoice(
      input.orgId,
      fullPeriodChargeCents(input.plan, subscription.seats, input.interval),
      periodStart,
      periodEnd,
    );
  } else {
    subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );

    if (
      current.status === "active" &&
      current.plan !== "free" &&
      input.plan !== "free"
    ) {
      const diffPerSeat =
        getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(current.plan).priceCentsPerSeatMonthly;

      if (diffPerSeat > 0) {
